  r.add('d', 1);
  r.add('e', 1);
  r.add('f', 1);
  r.add('g', 1);
  r.add('h', 1);
  r.complete('a');
  assert.equal(r.percentDone(), 13);
  r.complete('b');
  r.complete('c');
  assert.equal(r.percentDone(), 38);
});

test('progress errors', () => {
  const p = mk();
  assert.throws(() => p.complete('nope'), (e) => e instanceof PlanError && e.code === 'UNKNOWN');
  assert.throws(() => p.isComplete('nope'), (e) => e.code === 'UNKNOWN');
