  const p = mk();
  p.complete('release');
  p.remove('release');
  p.add('release', 1);
  assert.equal(p.isComplete('release'), false);
  assert.equal(p.percentDone(), 0);
});

test('report marks finished tasks', () => {
  const p = mk();
  p.complete('design');
  p.complete('docs');
  const lines = p.toText().split('\n');
  assert.equal(lines[0], 'design    0   3 ===');
  assert.equal(lines[1], 'build     3   8    #####');
  assert.equal(lines[3], 'docs      3   5    ==');
});

test('removing a task forgets its lags', () => {
  const p = new Plan();
  p.add('a', 1);
  p.add('b', 1, [{ name: 'a', lag: 3 }]);
  p.remove('b');
  p.add('b', 1, ['a']);
  assert.equal(p.lagOf('b', 'a'), 0);
