  assert.throws(() => p.add('a', 1), (e) => e instanceof PlanError && e.code === 'DUPLICATE');
  assert.throws(() => p.order(), (e) => e.code === 'UNKNOWN');
  assert.throws(() => p.get('zzz'), (e) => e.code === 'UNKNOWN');
  assert.throws(() => p.add('c', 0), RangeError);
});

