test('report', () => {
  const p = mk();
  const b = '*';
  assert.equal(
    p.toText(),
    `design    0   3 ${b.repeat(3)}\nbuild     3   8    ${b.repeat(5)}\ntest      8  10         ${b.repeat(2)}\ndocs      3   5    ${b.repeat(2)}\nrelease  10  11           ${b}\n`,
  );
  assert.equal(new Plan().toText(), '');
  const q = new Plan();
  q.add('x', 1);
  assert.equal(q.toText(), `x   0   1 ${b}\n`);
});

function sized(workers) {
