  assert.deepEqual(p.schedule(), {
    design: { start: 0, finish: 3 },
    build: { start: 3, finish: 8 },
    test: { start: 8, finish: 10 },
    docs: { start: 8, finish: 10 },
    release: { start: 10, finish: 11 },
  });
  assert.equal(p.duration(), 11);
});

