  const p = new Plan(options);
  p.add('design', 3);
  p.add('build', 5, ['design']);
  p.add('test', 2, ['build']);
  p.add('docs', 2, ['design']);
  p.add('release', 1, ['test', 'docs']);
  return p;
};

test('order and schedule', () => {
  const p = mk();
  assert.deepEqual(p.order(), ['design', 'build', 'test', 'docs', 'release']);
