test('progress', () => {
  const p = mk();
  assert.equal(p.percentDone(), 0);
  assert.equal(p.isComplete('docs'), false);
  p.complete('design');
  p.complete('design');
  assert.equal(p.percentDone(), 23);
  p.complete('docs');
  assert.equal(p.percentDone(), 38);
