  p.add('paint', 1);
  assert.deepEqual(p.add('frame', 3, [{ name: 'pour', lag: 4 }, 'paint']).deps, ['pour', 'paint']);
  p.add('roof', 1, ['frame', { name: 'paint', lag: 7 }]);
